        match JsonInterop.toNode (RecordJson.ToJson value) with
        | null -> System.Text.Json.Nodes.JsonObject() :> System.Text.Json.Nodes.JsonNode
        | node -> node

    /// The typed parse of a JSON value of runtime type `t`, or the first issue.
    static member TryFromJson(json: Json, t: Type) : Result<obj, string> =
        let decode = snd (RecordJson.Codec t)
        Decode.run decode json

    /// The typed parse of a JSON value; throws `FormatException` with the first issue.
    static member FromJson<'T>(json: Json) : 'T =
        match RecordJson.TryFromJson(json, typeof<'T>) with
        | Ok value -> unbox<'T> value
        | Error issue -> raise (FormatException issue)

    /// The typed parse of JSON text; throws `FormatException` for invalid JSON or the first issue.
    static member Parse<'T>(text: string) : 'T =
        match Json.parse text with
        | Ok json -> RecordJson.FromJson<'T> json
        | Error message -> raise (FormatException message)

    /// The typed parse of UTF-8 JSON.
    static member ParseUtf8<'T>(bytes: ReadOnlySpan<byte>) : 'T = RecordJson.Parse<'T>(System.Text.Encoding.UTF8.GetString bytes)

    /// The typed parse of a System.Text.Json node.
    static member FromNode<'T>(node: System.Text.Json.Nodes.JsonNode | null) : 'T = RecordJson.FromJson<'T>(JsonInterop.ofNode node)

    /// A deep copy through JSON (`JSON.parse(JSON.stringify(value))`).
    static member Clone<'T>(value: 'T) : 'T = RecordJson.FromJson<'T>(RecordJson.ToJson value)
